// services/storage.js — private document storage behind one interface
//   save(key, buffer) → key · read(key) → absolute path · remove(key)
// "local" keeps files in backend/uploads/private (never served publicly).
// A cloud driver (S3 / Cloudinary) can be added here without changing callers.
const fs   = require("fs/promises");
const path = require("path");
const config = require("../config/appConfig");

const ROOT = path.join(__dirname, "..", "uploads", "private");

// Keys are generated by the server (e.g. cnic/<userId>/front.jpg) — still guard against "../"
const resolveKey = (key) => {
  const full = path.resolve(ROOT, key);
  if (!full.startsWith(ROOT + path.sep)) throw new Error("Invalid storage key");
  return full;
};

const localDriver = {
  async save(key, buffer) {
    const full = resolveKey(key);
    await fs.mkdir(path.dirname(full), { recursive: true });
    await fs.writeFile(full, buffer);
    return key;
  },
  async read(key) {
    const full = resolveKey(key);
    await fs.access(full);
    return full;
  },
  async remove(key) {
    await fs.rm(resolveKey(key), { force: true });
  },
};

const drivers = { local: localDriver };

module.exports = drivers[config.uploads.driver] || localDriver;
